  ["Stereo module not installed."] = "Moduł stereo nie jest zainstalowany.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "Hooki silnika się nie wczytały, więc wszystko poniżej jest nieaktywne, a gogle działają w zwykłym trybie mono. Albo CyberpunkVR_StereoModuleEnable wynosi 0, albo istnieje bin\\x64\\vrport_nostereo.txt. Zobacz wiersz \"Stereo:\" w cyberpunkvrport.log.",
  ["LEFT"] = "LEWEGO",
  ["RIGHT"] = "PRAWEGO",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Stereo aktywne  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Teraz brak drugiego oka -> oba oczy dostają MAIN (mono)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "Normalne w menu i podczas wczytywania. Jeśli zostaje tak w grze: komponent VRCAM jest wyłączony albo vrcam.json wskazuje kamerę, której encja gracza nie ma.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Wysyłanie stereo wyłączone -> oba oczy dostają MAIN (mono)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "wiek oka vrcam %u ms  (nieaktualne po %u)   wysłań oka %llu",
  ["vrcam eye: never produced a frame"] = "oko vrcam: nigdy nie wygenerowało klatki",
  ["Send VRCAM to the %s EYE"] = "Wysyłaj VRCAM do %s OKA",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Wył. = stare zachowanie, MAIN powielane w obu oczach.\nWł. = oko %s dostaje własny końcowy kolor widoku VRCAM --\nten sam obraz, co lustro na pulpicie -- przekodowany do\nformatu sRGB swapchain i przeskalowany do rozmiaru oka.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "kopie migawki %llu   pominięcia %llu   trafienia RTV vrcam %llu",
  ["Eye staleness limit (ms)"] = "Limit nieaktualności oka (ms)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Jak długo ostatnia klatka VRCAM pozostaje użyteczna. Potem oko %s\nwraca do MAIN -- jedno zamrożone oko, gdy drugie się rusza,\njest dużo gorsze do oglądania niż mono.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (podąża za upscalerem MAIN, bez przełącznika)",
  ["ON"] = "WŁĄCZONE",
  ["off"] = "wył.",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "Włączone, gdy MAIN skaluje przez DLSS: vrcam dostaje własny\nviewport Streamline i renderuje poniżej docelowej rozdzielczości.\nWyłączone przy DLAA / TAA / bez upscalera. Zmienia się w ustawieniach\ngrafiki gry, nie tutaj.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "Dopasuj projekcję VRCAM do MAIN  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "Komponent VRCAM  (przełącznik RTTI: wymuś WŁ./WYŁ.)",
  ["component %s   camera %s"] = "komponent %s   kamera %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "węzły widoku: main %llu   inne %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "Lustro VRCAM  (osobne okno, do nagrywania)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Diagnostyka",
  ["Compact ADS camera telemetry (in-headset)"] = "Kompaktowa telemetria kamery ADS (w goglach)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "Mały panel, który zostaje po zamknięciu F10 i pokazuje, co SILNIK zrobił z kamerą przy podniesieniu celownika:\ndelta i szczyt w centymetrach, prawo/przód/góra w bazie kierunku, względem bazy zebranej przy strzelaniu z biodra.\nWysyłanie stereo nie jest zmieniane.",
  ["Telemetry X"] = "Telemetria X",
  ["Telemetry Y"] = "Telemetria Y",
  ["Normalised position in the eye image"] = "Znormalizowana pozycja w obrazie oka",
  ["Stereo logging -> cyberpunkvrport.log"] = "Dziennik stereo -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "Utrwalona migawka końcowego obrazu VRCAM",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Wył. = czytaj tymczasowy cel silnika bezpośrednio. Ten cel to\nalokacja frame graph, którą późniejszy przebieg używa ponownie, przez co\nobraz migał jasny/ciemny. Zostaw włączone.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "Migawka w węźle tonemap zamiast RenderFinal2D",
  ["Node CPU profiler  (per-node self+incl ms)"] = "Profiler CPU węzłów  (własne+łączne ms na węzeł)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "klatka %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Audyt węzłów -> dziennik  (resetuje okno)",
  ["top %d by self ms/frame   (main | vrcam)"] = "top %d wg własnych ms/klatkę   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Jazda -- ręce na kierownicy",
  ["Grab the wheel with the grips"] = "Chwytaj kierownicę gripami",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "Podczas JAZDY przyłóż dłoń tam, gdzie animacja jazdy trzyma\nkierownicę (lub kierownicę motocykla), i ściśnij grip: ramię wraca\ndo własnej animacji gry -- dłoń na kierownicy, palce zaciśnięte\nna niej -- zamiast podążać za kontrolerem. Puść grip, a wróci\ndo twojej dłoni.\n\nKażda dłoń działa niezależnie: trzymaj kierownicę jedną, a drugą\nbroń. Gdy dłoń jest na kierownicy, ten grip nie robi nic innego (nie\nwyjmuje z kabury, nie chwyta magazynka).",
  ["Grab radius (m)"] = "Promień chwytu (m)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Jak blisko animowanej dłoni musi być twoja dłoń, by\ngrip liczył się jako chwyt kierownicy. Większy = łatwiej złapać\nkierownicę, której nie widać; za duży, a każdy chwyt w aucie łapie kierownicę.",
  ["Car full lock at (deg)"] = "Pełny skręt przy (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Czułość kierownicy: obrót dłoni od miejsca chwytu do pełnego skrętu.\nJedna dłoń używa piasty skalibrowanej w miejscu chwytu; dwie — linii między nimi.\nDodanie lub puszczenie dłoni zachowuje bieżący skręt.\n180 = pół obrotu do oporu w każdą stronę (domyślnie). Mniej = czulej.\nKierownica w kabinie ma dwa razy większy zakres niż natywna; skręt kół się nie zmienia.\nZakres poza pełnym skrętem zachowuje to samo położenie neutralne.",
  ["Steering deadzone (deg)"] = "Martwa strefa skrętu (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Pochylenie wokół środka, które w ogóle nie skręca.\nZwiększ, jeśli auto ściąga, gdy trzymasz kierownicę prosto;\nkażdy stopień tutaj to stopień martwej kierownicy od środka.\nPełny zakres i tak kończy się na „Pełny skręt przy”, więc poszerzenie\nmartwej strefy nie powoduje skoku kierowania.",
  ["Steering prediction"] = "Przewidywanie skrętu",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "Delikatnie przewiduje dalszy skręt na podstawie ostatniego ruchu dłoni.\nOgraniczone do 8 ms i 0.5°; neutralne położenie się nie zmienia.\nPrzewidywanie zatrzymuje się przy pauzie, zmianie kierunku lub chwytu.\nDomyślnie wył. Nie przewidzi początku skrętu.",
  ["Prediction horizon (ms)"] = "Horyzont przewidywania (ms)",
  ["Horn -- hand on the wheel hub"] = "Klakson -- dłoń na środku kierownicy",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "Podczas JAZDY połóż dłoń na ŚRODKU kierownicy -- tam, gdzie\nuderzyłbyś w prawdziwy klakson -- a auto trąbi, dopóki tam jest.\nGrip niepotrzebny; dłoń, która TRZYMA kierownicę, nigdy nie trąbi.",
  ["Horn hub radius (m)"] = "Promień środka klaksonu (m)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Jak blisko środka kierownicy dłoń liczy się jako na piaście.\nWiększy = łatwiej znaleźć klakson bez patrzenia; za duży\ni sięga obręczy, więc każdy chwyt trąbi.",
  ["Trigger fires the gun while driving"] = "Spust strzela podczas jazdy",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Wyjmij broń na miejscu kierowcy, a PRAWY SPUST przestaje być\ngazem i staje się bronią: prowadź lewą ręką na kierownicy i\nstrzelaj prawą.\n\nGaz ZOSTAJE ZABLOKOWANY na wartości z chwili wyjęcia broni, więc\nauto dalej jedzie, a LEWA GAŁKA przód/tył reguluje prędkość, gdy\nstrzelasz. Schowaj broń, a spust znów będzie gazem.\n\nGdy broń jest wyjęta, przód/tył lewej gałki zajmuje\nregulacja: bez pochylania / kołysania i bez gestu autojazdy, dopóki nie schowasz broni.",
  ["Throttle trim rate (/s)"] = "Tempo regulacji gazu (/s)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "Jaką część pełnego zakresu gazu lewa gałka dodaje lub\nodejmuje na sekundę, gdy broń jest wyjęta.\n0.5 = dwie sekundy trzymania od biegu jałowego do pełnego gazu.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "jazda %d   na kierownicy  L %d R %d   chwyt  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "skręt  %+.1f°  ->  gałka %+.2f     klakson  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "PRZESUNIĘCIE KAMERY NA SIEDZĄCO",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "Przesunięcia głowy w OGÓLNE to kalibracja na stojąco. Na siedząco kamera pojazdu\ngry jest już tam, gdzie powinna -- dlatego port pomija\nswoje dwie automatyczne korekty w pojeździe -- więc przesunięcie na stojąco wyprowadza widok\nz fotela, zamiast go poprawiać.\n\nTe trzy są dodawane do suwaków głowy, gdy jesteś w pojeździe, i\nignorowane, gdy tylko wysiądziesz, więc auto i ulicę można stroić\nosobno. Zero = auto zachowuje dokładnie obecne przesunięcie.",
  ["Car Head X right"] = "Głowa w aucie X w prawo",
  ["Car Head Y forward"] = "Głowa w aucie Y do przodu",
