  ["Balanced"] = "Zrównoważony",
  ["Performance"] = "Wydajność",
  ["The center follows game DLSS/DLAA. Peripheral DLAA uses 100%% / 75%% / 50%% of the game's render resolution."] = "Środek podąża za DLSS/DLAA gry. DLAA na peryferiach używa 100%% / 75%% / 50%% rozdzielczości renderowania gry.",
