  ["Render sun cascades once for both eyes. Shadow quality and distance remain controlled by the game."] = "Renderuje kaskady słońca raz dla obu oczu. Jakość i zasięg cieni nadal ustala gra.",
  ["Scope lens stabilization"] = "Stabilizacja soczewki celownika",
  ["Magnifying scope lenses while the view moves: share of the stabilised image (percent). Higher: no blinking of lights and grates, softer. 0 = off. Standing still the lens is untouched."] = "Powiększające soczewki celowników podczas ruchu widoku: udział ustabilizowanego obrazu (procent). Więcej: bez migania świateł i krat, miękkiej. 0 = wył. W bezruchu soczewka się nie zmienia.",
  ["VARIABLE RATE SHADING"] = "CIENIOWANIE ZE ZMIENNĄ CZĘSTOTLIWOŚCIĄ",
  ["Peripheral shading"] = "Cieniowanie peryferii",
  [" 2 x 2"] = " 2 x 2",
  [" 4 x 4"] = " 4 x 4",
  ["Opaque scene materials in both eyes. The center stays 1 x 1. Unsupported 4 x 4 falls back to 2 x 2."] = "Nieprzezroczyste materiały sceny w obu oczach. Środek zostaje 1 x 1. Nieobsługiwane 4 x 4 przechodzi na 2 x 2.",
