  ["Disable Mouse Y (Pitch)"] = "Wyłącz oś Y myszy (pochylenie)",
  ["Suppress mouse/right-stick pitch so only the HMD controls\nvertical look. Applied by the CET VRIK mod and the\nXInput merge. On by default."] = "Tłumi pochylenie myszy/prawej gałki, by pionowym patrzeniem sterowały\ntylko gogle. Stosowane przez mod CET VRIK i\nscalanie XInput. Domyślnie wł.",
