  ["Verbose log (spammy diag)"] = "Szczegółowy dziennik (dużo diagnostyki)",
  ["Off by default for a clean cyberpunkvrport.log. Enable only\nwhen capturing ClipCursor / depth / hook diagnostics."] = "Domyślnie wył., by cyberpunkvrport.log był czysty. Włączaj tylko\nprzy zbieraniu diagnostyki ClipCursor / głębi / hooków.",
  ["FRAMEGEN"] = "GEN. KLATEK",
  ["Enable frame generation"] = "Włącz generowanie klatek",
  ["While frame generation is enabled, hand smoothing runs at its rate times xr_hand_lerp_framegen_scale (1.5; 0 turns it off)."] = "Przy włączonym generowaniu klatek wygładzanie dłoni działa z częstotliwością pomnożoną przez xr_hand_lerp_framegen_scale (1.5; 0 je wyłącza).",
