  ["DLSS Frame Generation is not available here (%s); FidelityFX is used."] = "DLSS Frame Generation nie jest tu dostępne (%s); używany jest FidelityFX.",
  ["NVIDIA optical flow is not available on this GPU; FidelityFX optical flow is used."] = "Przepływ optyczny NVIDIA nie jest dostępny na tym GPU; używany jest przepływ optyczny FidelityFX.",
  ["NVIDIA quality"] = "Jakość NVIDIA",
  ["Fast (performance)"] = "Szybko (wydajność)",
  ["Medium (balanced)"] = "Średnio (zrównoważony)",
  ["Slow (best)"] = "Wolno (najlepiej)",
  ["Optical flow"] = "Przepływ optyczny",
  ["Off (game vectors only)"] = "Wył. (tylko wektory gry)",
  ["The game's motion vectors already describe almost all motion; optical flow adds GPU time\nand memory for what they miss (some particles and effects)."] = "Wektory ruchu gry opisują już prawie cały ruch; przepływ optyczny dodaje czas GPU\ni pamięć dla tego, co pomijają (niektóre cząsteczki i efekty).",
  ["NVIDIA's frame generation model on the game's motion vectors and depth. Highest quality, RTX 40/50."] = "Model generowania klatek NVIDIA na wektorach ruchu i głębi gry. Najwyższa jakość, RTX 40/50.",
  ["Adaptive real-frame pacing"] = "Adaptacyjne tempo rzeczywistych klatek",
  ["Up to half headset refresh. Leaves more GPU time for generated frames when adjacent real frames are being missed."] = "Do połowy odświeżania gogli. Zostawia więcej czasu GPU na generowane klatki, gdy sąsiednie rzeczywiste klatki nie zdążają.",
  ["Uses game motion vectors and depth in both eyes. Adds one intermediate frame between real frames."] = "Używa wektorów ruchu i głębi gry w obu oczach. Dodaje jedną klatkę pośrednią między rzeczywistymi.",
  ["HUD"] = "HUD",
  ["Enable HUD panel"] = "Włącz panel HUD",
  ["Head / free-look cone"] = "Głowa / stożek swobodnego patrzenia",
  ["Follow"] = "Podążanie",
  ["Catch up beyond the cone, or after 3 seconds at rest when the yaw offset is over 10 degrees inside it."] = "Nadąża poza stożkiem lub po 3 sekundach bezruchu, gdy odchylenie w nim przekracza 10°.",
  ["HUD FOV"] = "FOV HUD",
  ["Stereo depth"] = "Głębia stereo",
  ["Off: the HUD has the same direction in both eyes.\nOn: place it at the selected physical depth."] = "Wył.: HUD ma ten sam kierunek w obu oczach.\nWł.: umieszcza go na wybranej głębi fizycznej.",
  ["Depth"] = "Głębia",
  ["Brightness"] = "Jasność",
  ["Shadow / outline"] = "Cień / obrys",
  ["Glow"] = "Poświata",
  ["INTERACTIONS / DIALOGS"] = "INTERAKCJE / DIALOGI",
  ["World-space interactions / dialogs"] = "Interakcje / dialogi w przestrzeni",
  ["Interaction free-look cone"] = "Stożek swobodnego patrzenia interakcji",
  ["Loot free-look cone"] = "Stożek swobodnego patrzenia łupów",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "Używany, gdy widoczny jest panel łupów i opis przedmiotu. Domyślnie: 10°.",
  ["Interaction distance"] = "Odległość interakcji",
  ["Interaction FOV"] = "FOV interakcji",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "Podpowiedzi interakcji i wybory dialogowe dzielą ten panel. Podąża tylko poza stożkiem; bez opóźnionego nadążania w bezruchu.",
  ["Element"] = "Element",
  ["Not currently visible in gameplay; settings are still saved."] = "Obecnie niewidoczny w grze; ustawienia i tak są zapisywane.",
  ["Show element"] = "Pokaż element",
  ["Horizontal offset"] = "Przesunięcie w poziomie",
  ["Vertical offset"] = "Przesunięcie w pionie",
  ["Size"] = "Rozmiar",
  ["Opacity"] = "Krycie",
  ["Reset element"] = "Zresetuj element",
  ["Reset all elements"] = "Zresetuj wszystkie elementy",
  ["CONTROLS"] = "STEROWANIE",
  ["DRIVING"] = "JAZDA",
  ["BINDINGS"] = "PRZYPISANIA",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Ruch, celowanie i skróty fizycznych interakcji.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "Celowanie dłonią  (wył. = oddzielne celowanie głową VR)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "WŁ. (celowanie dłonią): kontroler kieruje bronią, a VRIK porusza ramionami.\nWYŁ. (oddzielne celowanie głową VR): BROŃ podąża za głową, gra\nzachowuje jej pozycję i animacje ADS, a VRIK puszcza\nramię z bronią. Tak czy inaczej strzał wychodzi z prawdziwej lufy, zarówno dla kul,\njak i pocisków, a swobodne patrzenie przy celowaniu zostaje.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Laserowa kropka celownika (gdzie trafi kula)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "Czerwona kropka rzutowana z rzeczywistego kierunku lufy przez\nkamerę gry -- pokazuje dokładnie, gdzie poleci kula.",
  ["Controller vibration"] = "Wibracje kontrolerów",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Haptyka: każdy strzał wg klasy broni (pistolet, karabin, strzelba, snajperka),\nblok i parowanie w walce wręcz, blok i odbicie kul, sięgnięcie po element pasa,\nwyrwanie zawleczki granatu. Chwyt oburącz: obie dłonie; jedną ręką: jedna.",
  ["Vibration strength"] = "Siła wibracji",
  ["Enable VR -> XInput merge"] = "Włącz scalanie VR -> XInput",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Łączy (OR) stan kontrolerów VR z padem XInput 0 przy każdym odczycie.\nWył. = gra widzi tylko fizyczny pad / nic.",
  ["Weapon holsters (reach + right grip)"] = "Kabury broni (sięgnij + prawy grip)",
  ["Immersive holsters"] = "Immersyjne kabury",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "WŁ.  - broń wybiera WIDOCZNA kabura, po którą sięgasz:\n      nad prawym ramieniem = broń główna (karabin / snajperka),\n      biodro z kataną = walka wręcz, biodro z pistoletem = broń boczna.\nWYŁ. - widoczne kabury ignorowane, stały slot na strefę:\n      nad ramieniem = EquipmentSlot1, prawe biodro = Slot2, lewe biodro = Slot3.\nSięgnij do strefy i ściśnij PRAWY grip, by wyjąć / schować.",
  ["Locomotion direction"] = "Kierunek ruchu",
  ["Analog movement"] = "Ruch analogowy",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "Wł.: prędkość podąża za wychyleniem lewej gałki. Wył.: obecny ruch ze stałą prędkością (domyślnie).\nSterowanie pojazdami zachowuje dotychczasową reakcję.",
  ["Left stick deadzone"] = "Martwa strefa lewej gałki",
  ["Right stick deadzone"] = "Martwa strefa prawej gałki",
  ["Full input threshold"] = "Próg pełnego wychylenia",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Surowe wychylenie dające pełne wejście analogowe i włączające sprint, unik i kucanie.\nUżyteczny zakres między martwą strefą a tym progiem odpowiada 0-100%%.",
  ["Game (camera)"] = "Gra (kamera)",
  ["HMD (head)"] = "HMD (głowa)",
  ["Left hand"] = "Lewa dłoń",
  ["Right hand"] = "Prawa dłoń",
  ["Move source"] = "Źródło kierunku ruchu",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Gra      - lewa gałka idzie tam, gdzie patrzy kamera (oryginalnie).\nHMD      - lewa gałka idzie tam, gdzie patrzą gogle.\nLewa/prawa dłoń - idzie tam, gdzie wskazuje wybrany kontroler.\nPojazdy zawsze zachowują kierunek gry.",
  ["Breaststroke swimming"] = "Pływanie żabką",
  ["Physical crouch"] = "Fizyczne kucanie",
  ["Physical crouch depth"] = "Głębokość fizycznego kucania",
  ["%.0f cm"] = "%.0f cm",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Utrata wysokości po zmierzonym pochyleniu. Wyprostowanie kończy fizyczne kucanie.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "W wodzie: sięgnij obiema dłońmi do przodu, rozsuń je na boki i pociągnij do tyłu.\nRuch zaczyna się podczas pociągnięcia. Spokojne ruchy to zwykłe pływanie; szybkie dają przyspieszenie.\nPłyniesz tam, gdzie wskazują gogle, także w górę/dół; gałka niepotrzebna.\nAby się wynurzyć, unieś rozsunięte dłonie do piersi i pchnij obie w dół.\nPowtarzaj ruchy, by płynąć dalej. Pociągnij lewą gałkę do tyłu, by się zatrzymać.",
  ["Ladder grip climbing"] = "Wspinaczka po drabinie gripami",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Chwyć boczny słupek lub szczebel. Ciągnij dłoń w dół, by wspinać się w górę,\nlub przesuń ją w górę, by schodzić. Puść, by się zatrzymać. Natywna miednica i nogi zostają na drabinie.",
  ["Auto finish near ladder top"] = "Automatyczne dokończenie u szczytu drabiny",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "Po pociągnięciu w górę przy szczycie wspinaczka się kończy, nawet gdy gripy są puszczone.\nRusz gałką albo pchnij trzymającą dłoń w górę, by anulować.",
  ["Ladder finish distance"] = "Odległość dokończenia drabiny",
  ["Turning (right stick)"] = "Obrót (prawa gałka)",
  ["Snap turn"] = "Obrót skokowy",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "Zamienia oś X prawej gałki na osobne skoki obrotu\nzamiast płynnego obracania. Pomaga przy chorobie lokomocyjnej.",
  ["Snap angle"] = "Kąt skoku",
  ["STEREO"] = "STEREO",
  ["PERFORMANCE"] = "WYDAJNOŚĆ",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Ustawienie gry",
  ["Off (higher FPS)"] = "Wył. (więcej FPS)",
  ["On (lower latency)"] = "Wł. (mniejsze opóźnienie)",
  ["On + Boost"] = "Wł. + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "Wył. może poprawić wykorzystanie GPU i FPS, ale może zwiększyć opóźnienie sterowania.",
  ["On"] = "Wł.",
  ["Waiting for renderer"] = "Oczekiwanie na renderer",
  ["Applied: %s"] = "Zastosowano: %s",
  ["STEREO VIEW"] = "WIDOK STEREO",
  ["Mono mode"] = "Tryb mono",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Jeden obraz dla obu oczu, renderowany raz ze środka głowy:\nbez głębi, najwięcej klatek. Stereo silnika i drugi widok są wyłączone.",
  ["Restart the game to apply"] = "Uruchom grę ponownie, aby zastosować",
  ["Motion prediction (ms)"] = "Przewidywanie ruchu (ms)",
  ["%.1f ms"] = "%.1f ms",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Przewiduje pozę głowy o tyle ms do przodu na podstawie jej\nprędkości, ukrywając opóźnienie od renderowania do fotonów. 0 = wył.\nZwiększaj, aż ruch będzie responsywny bez przestrzelenia.",
  ["Stereo separation x"] = "Rozstaw stereo x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Osobista korekta automatycznego IPD. 1.0 = skalibrowany naturalny\nrozstaw, automatycznie skalowany do IPD środowiska gogli. Przesuwaj\n0.8-1.2 do gustu; 3-5x przesadza głębię i sprawia, że\nnaprzemienność oczu jest widoczna na płaskim monitorze do testów.",
  ["World scale"] = "Skala świata",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Skaluje razem rozstaw oczu I przesunięcie głowy.\nZmniejsz (np. 0.8), by świat wyglądał na\nWIĘKSZY / ty na mniejszego; zwiększ, by świat się zmniejszył. Użyj, jeśli V\ni NPC wydają się za duzi.",
  ["IPD scale"] = "Skala IPD",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Mnożnik rozstawu oczu względem IPD środowiska. 1.0 = neutralna\nbaza (+-0.033 m w typowych goglach).\nWpływa na głębię stereo (diorama czy olbrzym), NIE na rozmiar jednooczny.",
  ["Reuse last clean frame"] = "Użyj ponownie ostatniej czystej klatki",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "Przy nieaktualnych taktach ponownie wysyła ostatnie czyste przechwycone oko i pozwala\nkompozytorowi je reprojekcjonować, zamiast znów zniekształcać nieaktualną\nzawartość. Może obniżyć częstotliwość wysyłania\ndo częstotliwości przechwytywania. Wył. = zawsze zniekształcaj nieaktualne oko.",
  ["Asymmetric projection"] = "Projekcja asymetryczna",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "WŁ.: każde oko renderuje dokładnie własne przesunięte okno soczewki\n(więcej panelu w użyciu, kwadratowe piksele).\nWYŁ.: symetryczny ostrosłup dopasowany do najszerszego półkąta.",
  ["AVATAR"] = "AWATAR",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "Skróty VR i domyślne akcje gry. Nazwy przycisków według konwencji Touch / Xbox; akcje gry używają twoich przypisań kontrolera.",
